// Regenerate after upgrading intl: dart run tools/generate_date_locales.dart
import 'dart:io';

import 'package:intl/date_symbol_data_local.dart' as local;
import 'package:intl/date_time_patterns.dart' as patterns;

void main() {
  final symbols = local.dateTimeSymbolMap();
  const locales = ['en_US', 'id'];
  final output = StringBuffer(
    '''// Generated by tools/generate_date_locales.dart from intl's CLDR data.
// Copyright (c) 2014, the Dart project authors. BSD-3-Clause.
// See THIRD_PARTY_NOTICES/intl-LICENSE.
// Do not import date_symbol_data_local in production: it retains all locales.
import 'package:intl/date_symbol_data_custom.dart';
import 'package:intl/date_symbols.dart';

/// Registers Indonesian dates and the default English format used by the app.
void initializeAppDateFormatting() {
''',
  );
  for (final locale in locales) {
    final data = symbols[locale]!.serializeToMap();
    output.writeln('  initializeDateFormattingCustom(');
    output.writeln('    locale: ${literal(locale)},');
    output.writeln('    symbols: DateSymbols(');
    for (final entry in data.entries) {
      output.writeln('      ${entry.key}: ${literal(entry.value)},');
    }
    output.writeln('    ),');
    output.writeln(
      '    patterns: <String, String>${literal(patterns.dateTimePatternMap()[locale]!)},',
    );
    output.writeln('  );');
  }
  output.writeln('}');
  File('lib/core/utils/app_date_formatting.dart').writeAsStringSync('$output');
}

String literal(Object? value) {
  if (value is String) {
    final escaped = value
        .replaceAll('\\', '\\\\')
        .replaceAll("'", "\\'")
        .replaceAll(r'$', r'\$')
        .replaceAll('\n', r'\n')
        .replaceAll('\r', r'\r');
    return "'$escaped'";
  }
  if (value is List) return '[${value.map(literal).join(', ')}]';
  if (value is Map) {
    return '{${value.entries.map((e) => '${literal(e.key)}: ${literal(e.value)}').join(', ')}}';
  }
  return '$value';
}
